/// <summary>
/// Collect error
/// </summary>
/// <returns>String</returns>
private str getErrorStr()
{
    SysInfologEnumerator enumerator;
    SysInfologMessageStruct msgStruct;
    Exception exception;
    str error;
    enumerator = SysInfologEnumerator::newData(infolog.cut());
    while (enumerator.moveNext())
    {
        msgStruct = new SysInfologMessageStruct(enumerator.currentMessage());
        exception = enumerator.currentException();
        error = strfmt("%1 %2", error, msgStruct.message());
    }

    return error;
}

/// <summary>
/// Update Vendor Rebate
/// </summary>
/// <param name = "_vendorRebateRequest">METVendorRebateRequest</param>
/// <returns>METVendorRebateResponse</returns>
public METVendorRebateResponse updateVendorRebate(METVendorRebateRequest _vendorRebateRequest)
{
    TAMRebateDeal tamRebateDeal;
    Description255      message;
    container           resultCon;
    METProcessingStatus result;

    changecompany(_vendorRebateRequest.parmDataAreaId())
    {
        try
        {
            ttsbegin;
            select firstonly RecId from tamRebateDeal
                where tamRebateDeal.Deal == _vendorRebateRequest.parmVendorRebateDealContract().parmTAMRebateDealId();

            if (tamRebateDeal)
            {
                resultCon = this.updateDeal(_vendorRebateRequest.parmVendorRebateDealContract());
                result = conPeek(resultCon, 1);
                message = conPeek(resultCon, 2);
                vendAccount= conPeek(resultCon, 3);
                metExternalRebateDealReference = conPeek(resultCon, 4);
                tamRebateDealId = conPeek(resultCon, 5);
                tamRebateFromDate = conPeek(resultCon, 6);
                tamRebateToDate = conPeek(resultCon, 7);
                tamRebateActive = conPeek(resultCon, 8);
                metRebateDealType =  conPeek(resultCon, 9);
            }
            else
            {
                result = METProcessingStatus::Error;
                message = "@MET:VendRebateOldDealExist";
            }

            ttscommit;
        }
        catch(Exception::CLRError)
        {
            System.Exception interopException = CLRInterop::getLastException();

            result = METProcessingStatus::Error;

            if (interopException)
            {
                message = interopException.ToString();
            }
            else
            {
                message = this.getErrorStr();
            }
        }
        catch
        {
            System.Exception interopException = CLRInterop::getLastException();

            result = METProcessingStatus::Error;

            if (interopException)
            {
                message = interopException.ToString();
            }
            else
            {
                message = this.getErrorStr();
            }
        }
    }

    return METVendorRebateResponse::newFromParameters(result, message, vendAccount, metExternalRebateDealReference, tamRebateDealId, tamRebateFromDate, tamRebateToDate, tamRebateActive, metRebateDealType);
}

/// <summary>
/// Create Vendor Rebate
/// </summary>
/// <param name = "_vendorRebateRequest">METVendorRebateRequest</param>
/// <returns>METVendorRebateResponse</returns>
public METVendorRebateResponse createVendorRebate(METVendorRebateRequest _vendorRebateRequest)
{
    TAMRebateDeal tamRebateDeal, tamRebateDealWorkflow;
    METVendorRebateTableContract metVendorRebateTableContract;
    List tamRebateTableList;
    ListIterator literator;
    Description255 message;
    container   resultCon;
    METProcessingStatus result;

    changecompany(_vendorRebateRequest.parmDataAreaId())
    {
        try
        {
            ttsbegin;

            if (_vendorRebateRequest.parmVendorRebateDealContract().parmTAMRebateDealId())
            {
                select firstonly RecId, Deal, RebateFromDate, METVendAccount, METExternalRebateDealReference, METRebateDealType from tamRebateDeal
                    where tamRebateDeal.Deal == _vendorRebateRequest.parmVendorRebateDealContract().parmTAMRebateDealId();

                if (tamRebateDeal.Deal)
                {
                    result = METProcessingStatus::Error;
                    message = "@MET:VendRebateNewDealExist";
                    tamRebateDealId = tamRebateDeal.Deal;
                    tamRebateFromDate = tamRebateDeal.RebateFromDate;
                    vendAccount = tamRebateDeal.METVendAccount;
                    metExternalRebateDealReference = tamRebateDeal.METExternalRebateDealReference;
                    metRebateDealType = tamRebateDeal.METRebateDealType;

                    return METVendorRebateResponse::newFromParameters(result, message, vendAccount, metExternalRebateDealReference, tamRebateDealId, tamRebateFromDate, tamRebateToDate, tamRebateActive, metRebateDealType);
                }
            }                

            if (_vendorRebateRequest.parmVendorRebateDealContract())
            {
                resultCon = this.createHeader(_vendorRebateRequest.parmVendorRebateDealContract(), _vendorRebateRequest.parmDataAreaId());
                result = conPeek(resultCon, 1);
                message = conPeek(resultCon, 2);
                tamRebateDealWorkflow = conPeek(resultCon, 3);
                vendAccount= conPeek(resultCon, 4);
                metExternalRebateDealReference = conPeek(resultCon, 5);
                tamRebateDealId = conPeek(resultCon, 6);
                tamRebateFromDate = conPeek(resultCon, 7);
                tamRebateToDate = conPeek(resultCon, 8);
                tamRebateActive = conPeek(resultCon, 9);
                metRebateDealType =  conPeek(resultCon, 10);
                if (result == METProcessingStatus::Success)// If Rebate deal is created then create other records
                {
                    tamRebateTableList = _vendorRebateRequest.parmMETVendorRebateTableContractArray();
                    if (tamRebateTableList)
                    {
                        literator = new ListIterator(tamRebateTableList);
                        while (literator.more())
                        {
                            metVendorRebateTableContract = literator.value();
                            resultCon = this.createRebateTable(metVendorRebateTableContract, tamRebateDealId);
                            result = conPeek(resultCon, 1);
                            message += conPeek(resultCon, 2);
                            literator.next();
                        }
                        if(result == METProcessingStatus::Success) // Once agreement header and lines are created submit the workflow
                        {
                            this.submitWorkflow(tamRebateDealWorkflow);
                        }
                    }
                }                    
            }              

            ttscommit;
        }
        catch(Exception::CLRError)
        {
            System.Exception interopException = CLRInterop::getLastException();

            result = METProcessingStatus::Error;

            if (interopException)
            {
                message = interopException.ToString();
            }
            else
            {
                message = this.getErrorStr();
            }
        }
        catch
        {
            System.Exception interopException = CLRInterop::getLastException();

            result = METProcessingStatus::Error;

            if (interopException)
            {
                message = interopException.ToString();
            }
            else
            {
                message = this.getErrorStr();
            }
        }
        finally
        {
            if (resultCon == conNull())
            {
                METVendorRebateDealContract metVendorRebateDealContract = _vendorRebateRequest.parmVendorRebateDealContract();
                vendAccount = metVendorRebateDealContract.parmVendAccount();
                metExternalRebateDealReference = metVendorRebateDealContract.parmMETExternalRebateDealReference();
                tamRebateDealId = metVendorRebateDealContract.parmTAMRebateDealId();
                tamRebateFromDate = metVendorRebateDealContract.parmTAMRebateFromDate();
                tamRebateToDate = metVendorRebateDealContract.parmTAMRebateToDate();     
                metRebateDealType = metVendorRebateDealContract.parmMETRebateDealType();
            }
        }
    }       

    return METVendorRebateResponse::newFromParameters(result, message, vendAccount, metExternalRebateDealReference, tamRebateDealId, tamRebateFromDate, tamRebateToDate, tamRebateActive, metRebateDealType);
}

/// <summary>
/// Submit workflow
/// </summary>
/// <param name = "_tamRebateDeal">TAMRebateDeal</param>
public void submitWorkflow(TAMRebateDeal _tamRebateDeal)
{
    TAMRebateTable tamRebateTable;
    TAMRebateDeal tamRebateDeal = _tamRebateDeal, tamRebateDealUpdate;       

    select firstonly RecId from tamRebateTable 
        where tamRebateTable.RebateDeal == _tamRebateDeal.RecId
        && tamRebateTable.METAutoApproval == NoYes::No;

    if (tamRebateDeal && !tamRebateTable)
    {
        // Check whether we have an active workflow on the table.
        WorkflowVersionTable workflowVersionTable = Workflow::findWorkflowConfigToActivateForType(workFlowTypeStr(TAMRebateDeal),tamRebateDeal.RecId,tamRebateDeal.TableId);

        // If workflow is active, then submit the workflow.
        if (tamRebateDeal.RecId && workflowVersionTable.RecId)
        {
            // Submitting to workflow
            Workflow::activateFromWorkflowType(workFlowTypeStr(TAMRebateDeal),tamRebateDeal.RecId,"@AccountsPayable:VendBankAccountChangeProposalWorkflow_Submited",false,curUserid());

            // Update revision workflow status to submitted
            tamRebateDealUpdate = TAMRebateDeal::find(tamRebateDeal.RecId,true);
            tamRebateDealUpdate.State = TAMRebateDealWorkflowState::Submitted;
            tamRebateDealUpdate.update();
        }
    }
}

/// <summary>
/// Update Vendor Rebate Deal
/// </summary>
/// <param name = "_metVendorRebateDealContract">METVendorRebateDealContract</param>
/// <returns>container</returns>
public container updateDeal(METVendorRebateDealContract _metVendorRebateDealContract)
{
    #OCCRetryCount
    METProcessingStatus result;
    Description255  message;
    TAMRebateDeal tamRebateDeal;
    TAMRebateDate tamRebateDateUpdate;
    TAMRebateTable tamRebateTableUpdate;

    try
    {
        if ( _metVendorRebateDealContract.parmTAMRebateDealId())
        {
            select firstonly forupdate tamRebateDeal where tamRebateDeal.Deal == _metVendorRebateDealContract.parmTAMRebateDealId();
            tamRebateDeal.RebateToDate = _metVendorRebateDealContract.parmTAMRebateToDate();
            tamRebateDeal.update();
            update_recordSet tamRebateDateUpdate
            setting RebateToDate = tamRebateDeal.RebateToDate
            exists join tamRebateTableUpdate
            where tamRebateTableUpdate.RebateId == tamRebateDateUpdate.RebateId
            && tamRebateTableUpdate.RebateDeal == tamRebateDeal.RecId;

            result = METProcessingStatus::Success;
            message = "@SYS315570";
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                result = METProcessingStatus::Error;
                message = this.getErrorStr();
            }
            else
            {
                retry;
            }
        }
        else
        {
            result = METProcessingStatus::Error;
            message = this.getErrorStr();
        }
    }
    catch
    {
        result = METProcessingStatus::Error;
        message = this.getErrorStr();
    }

    return [result, message, tamRebateDeal.METVendAccount, tamRebateDeal.METExternalRebateDealReference, tamRebateDeal.Deal, tamRebateDeal.RebateFromDate, tamRebateDeal.RebateToDate, tamRebateDeal.RebateActive, tamRebateDeal.METRebateDealType];

}

/// <summary>
/// Create Vendor Deal
/// </summary>
/// <param name = "_metVendorRebateDealContract">METVendorRebateDealContract</param>
/// <returns>container</returns>
public container createHeader(METVendorRebateDealContract _metVendorRebateDealContract, DataAreaId _dataAreaId)
{
    #OCCRetryCount
    METProcessingStatus result;
    Description255  message;
    TAMRebateDeal tamRebateDeal;        

    try
    {
        tamRebateDeal.RebateCompanyId = _dataAreaId;
        tamRebateDeal.StatusId = TAMRebateParameters::find().DefaultRebateStatusId;
        tamRebateDeal.RebateActive = NoYes::Yes;
        tamRebateDeal.State = TAMRebateDealWorkflowState::Draft;
        if (_metVendorRebateDealContract.parmTAMRebateDealId())        
        {
            tamRebateDeal.Deal = _metVendorRebateDealContract.parmTAMRebateDealId();
        }
        else
        {
            tamRebateDeal.Deal = NumberSeq::newGetNum(TAMRebateParameters::numRefRebateDealId(), false).num();
        }       

        tamRebateDeal.ModuleInventCustVend = _metVendorRebateDealContract.parmModuleInventCustVend();
        tamRebateDeal.RebateCurrencyCode = _metVendorRebateDealContract.parmTAMRebateCurrencyCode();
        tamRebateDeal.Description = _metVendorRebateDealContract.parmDescription();
        tamRebateDeal.METVendAccount = _metVendorRebateDealContract.parmVendAccount();
        if (!tamRebateDeal.METVendAccount)
        {
            throw Error(strFmt("@RebatesAndDeductions:FieldMustBeSpecified", fieldPName(TAMRebateDeal, METVendAccount)));
            //Exception::Error;
        }
        tamRebateDeal.RebateOutputType = _metVendorRebateDealContract.parmTAMRebateOutputType();
        tamRebateDeal.RebateReconciliation = _metVendorRebateDealContract.parmTAMRebateReconciliation();
        tamRebateDeal.RebateType = _metVendorRebateDealContract.parmTAMRebateType();
        tamRebateDeal.METExternalRebateDealReference = _metVendorRebateDealContract.parmMETExternalRebateDealReference();
        tamRebateDeal.METUseExternalSellData = _metVendorRebateDealContract.parmMETUseExternalSellData();
        tamRebateDeal.RebatePostingId = _metVendorRebateDealContract.parmTAMRebatePostingId();
        tamRebateDeal.RebateFromDate = _metVendorRebateDealContract.parmTAMRebateFromDate();
        tamRebateDeal.RebateToDate = _metVendorRebateDealContract.parmTAMRebateToDate();
        tamRebateDeal.RebateActive = false;
        tamRebateDeal.METRebateDealType = _metVendorRebateDealContract.parmMETRebateDealType();
        tamRebateDeal.METInvoiceConsolidationByRebateType = _metVendorRebateDealContract.parmMETInvoiceConsolidationByRebateType();
        tamRebateDeal.RebateAgreementType = _metVendorRebateDealContract.parmRebateAgreementType();
        tamRebateDeal.insert();
        result = METProcessingStatus::Success;
        message = strFmt("@MET:RebateDealCreated",tamRebateDeal.Deal);

    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                result = METProcessingStatus::Error;
                message = this.getErrorStr();
            }
            else
            {
                retry;
            }
        }
        else
        {
            result = METProcessingStatus::Error;
            message = this.getErrorStr();
        }
    }
    catch (Exception::Error)
    {
        System.Exception interopException = CLRInterop::getLastException();

        result = METProcessingStatus::Error;

        if (interopException)
        {
            message = interopException.ToString();
        }
        else
        {
            message = this.getErrorStr();
        }
    }
    catch
    {
        result = METProcessingStatus::Error;
        message = this.getErrorStr();
    }

    return [result, message, tamRebateDeal, tamRebateDeal.METVendAccount, tamRebateDeal.METExternalRebateDealReference, tamRebateDeal.Deal, tamRebateDeal.RebateFromDate, tamRebateDeal.RebateToDate, tamRebateDeal.RebateActive, tamRebateDeal.METRebateDealType];
}

/// <summary>
/// Create Rebate table record
/// </summary>
/// <param name = "_metVendorRebateTableContract">METVendorRebateTableContract</param>
/// <returns>container</returns>
public container createRebateTable(METVendorRebateTableContract _metVendorRebateTableContract, TAMRebateDealId _tamRebateDealId)
{
    #OCCRetryCount
    GUPTAMRebateAndDeductionsAgreementHeaderEntity rebateTable;
    List tamRebateDateList,tamRebateLineList;
    METTAMRebateDateContract metTAMRebateDateContract;
    METTAMRebateLineContract metTAMRebateLineContract;
    ListIterator   literator;
    METProcessingStatus result;
    Description255  message;
    container resultCon;

    try
    {
        rebateTable.AgreementNumber = _metVendorRebateTableContract.parmAgreementNumber();
        rebateTable.AgreementDescription = _metVendorRebateTableContract.parmAgreementDescription();
        rebateTable.CalculationMethod = _metVendorRebateTableContract.parmCalculationMethod();
        rebateTable.AgreementModule = _metVendorRebateTableContract.parmAgreementModule();
        rebateTable.AveragePurchasePriceBasisCalculationMonthRange = _metVendorRebateTableContract.parmAveragePurchasePriceBasisCalculationMonthRange();
        rebateTable.MinimumAmount = _metVendorRebateTableContract.parmMinimumAmount();
        rebateTable.OperationalSiteId = _metVendorRebateTableContract.parmOperationalSiteId();
        rebateTable.RebateAndDeductionsDealNumber = _tamRebateDealId;
        rebateTable.UnitSymbol = _metVendorRebateTableContract.parmUnitSymbol();
        rebateTable.METRebateDiscountValue = _metVendorRebateTableContract.parmMETRebateDiscountValue();
        rebateTable.Header1 = _metVendorRebateTableContract.parmHeader1();
        rebateTable.Line1 = _metVendorRebateTableContract.parmLine1();
        rebateTable.Line2 = _metVendorRebateTableContract.parmLine2();
        rebateTable.Line3 = _metVendorRebateTableContract.parmLine3();
        rebateTable.Line4 = _metVendorRebateTableContract.parmLine4();
        rebateTable.Line5 = _metVendorRebateTableContract.parmLine5();
        rebateTable.Line6 = _metVendorRebateTableContract.parmLine6();
        rebateTable.Line7 = _metVendorRebateTableContract.parmLine7();
        rebateTable.Line8 = _metVendorRebateTableContract.parmLine8();
        rebateTable.METPriceComponentCode = _metVendorRebateTableContract.parmMetPriceComponentName();
        rebateTable.PriceComponentCodeName = _metVendorRebateTableContract.parmMetPriceComponentName();
        rebateTable.METPriceAttributeGroupCombination = _metVendorRebateTableContract.parmMetPriceAttributeGroupCombination();
        rebateTable.PriceComponentCombinationName = _metVendorRebateTableContract.parmMetPriceAttributeGroupCombination();

        //Transform attribute values
        GUPPricingAttributeLink attributeLink;
        int num = 1;
        const str baseFieldName = 'Line';
        const str ecoResProductCategoryConst = "EcoResProductCategory";
        const str categoryConst = "Category";
        str delimiter = GUPPricingRuleConditionRankView::getDelimiter();

        var combination = GUPPriceComponentCodePriceAttributeGroupCombination::findByNameAndComponentTypeAndCodeName(rebateTable.PriceComponentCombinationName, GUPPriceComponent::RebateManagement, rebateTable.PriceComponentCodeName);            

        while select RecId, SourceName, FieldName from attributeLink
        order by attributeLink.Priority desc
        where attributeLink.PriceAttributeGroupName == combination.LinePriceAttributeGroupName
        {
            str newFieldValue;
            str conditionValue = rebateTable.getFieldValue(baseFieldName + int2Str(num));
            if (attributeLink.SourceName == ecoResProductCategoryConst && attributeLink.FieldName == categoryConst)
            {
                List categoryList = new List(Types::String);
                List conditionList = strSplit(conditionValue, METConstants::Comma);
                ListEnumerator enumerator = conditionList.getEnumerator();
                while (enumerator.moveNext())
                {
                    str categoryStructure = enumerator.current();

                    if (categoryStructure == '')
                    {
                        continue;
                    }

                    EcoResCategoryHierarchy ecoResCategoryHierarchy;
                    EcoResCategory ecoResCategory;

                    select firstonly Name, RecId from ecoResCategoryHierarchy
                        where ecoResCategoryHierarchy.RecId == EcoResCategoryHierarchyRole::getHierarchiesByRole(EcoResCategoryNamedHierarchyRole::Retail).CategoryHierarchy;

                    if (ecoResCategoryHierarchy.Name)
                    {
                        select Name from ecoResCategory
                            where ecoResCategory.CategoryHierarchy == ecoResCategoryHierarchy.RecId && ecoResCategory.Code == categoryStructure;

                        if (newFieldValue)
                        {
                            newFieldValue += METConstants::Comma + ecoResCategoryHierarchy.Name + delimiter + ecoResCategory.Name;
                        }
                        else
                        {
                            newFieldValue = ecoResCategoryHierarchy.Name + delimiter + ecoResCategory.Name;
                        } 
                    }                        
                }
                rebateTable.setFieldValue(baseFieldName + int2Str(num), newFieldValue);                    
                num++;
            }
        }

        //Auto calculated fields
        GUPPriceComponentCodePriceAttributeGroupCombination gupPriceComponentCodePriceAttributeGroupCombination;

        select firstonly RecId, HeaderPriceAttributeGroupName, LinePriceAttributeGroupName  from gupPriceComponentCodePriceAttributeGroupCombination
        where gupPriceComponentCodePriceAttributeGroupCombination.Name == _metVendorRebateTableContract.parmMetPriceAttributeGroupCombination()
        && gupPriceComponentCodePriceAttributeGroupCombination.PriceComponentCodeName == _metVendorRebateTableContract.parmMetPriceComponentName();

        rebateTable.METHeaderPriceAttributeGroup = gupPriceComponentCodePriceAttributeGroupCombination.HeaderPriceAttributeGroupName;
        rebateTable.METLinePriceAttributeGroup = gupPriceComponentCodePriceAttributeGroupCombination.LinePriceAttributeGroupName;

        rebateTable.METSkipPosting = _metVendorRebateTableContract.parmMetSkipPosting();
        rebateTable.METVendAccount = _metVendorRebateTableContract.parmMetVendorAccount();
        rebateTable.METAutoApproval = _metVendorRebateTableContract.parmMetAutoApproval();
        rebateTable.ProductUnitSymbolType = _metVendorRebateTableContract.parmProductUnitSymbolType();
        rebateTable.RebateCalculationBasis = _metVendorRebateTableContract.parmRebateCalculationBasis();
        rebateTable.RebatePriceBasis = _metVendorRebateTableContract.parmRebatePriceBasis();
        rebateTable.SourceDocumentType = _metVendorRebateTableContract.parmSourceDocumentType();
        rebateTable.LegalEntityId = curExt();
        rebateTable.RebateAndDeductionsType = _metVendorRebateTableContract.parmRebateAndDeductionsType();
        rebateTable.VendorRebateCalculationTransactionBasis = _metVendorRebateTableContract.parmVendorRebateCalculationTransactionBasis();
        rebateTable.WillRebateProcessingCalculationIncludeCreditNote = _metVendorRebateTableContract.parmWillRebateProcessingCalculationIncludeCreditNote();
        rebateTable.WillRebateProcessingCalculationIncludeDiscountedAmount = _metVendorRebateTableContract.parmWillRebateProcessingCalculationIncludeDiscountedAmount();
        rebateTable.WillRebateProcessingCalculationIncludeFreeText = _metVendorRebateTableContract.parmWillRebateProcessingCalculationIncludeFreeText();
        rebateTable.WillRebateProcessingCalculationIncludePaidInvoicesOnly = _metVendorRebateTableContract.parmWillRebateProcessingCalculationIncludePaidInvoicesOnly();
        rebateTable.WillRebateProcessingCalculationIncludeSettlementDiscount = _metVendorRebateTableContract.parmWillRebateProcessingCalculationIncludeSettlementDiscount();
        rebateTable.WillRebateProcessingCalculationIncludeTax = _metVendorRebateTableContract.parmWillRebateProcessingCalculationIncludeTax();
        rebateTable.AveragePurchasePriceBasisCalculationMonthRange = _metVendorRebateTableContract.parmAveragePurchasePriceBasisCalculationMonthRange();
        rebateTable.RebateAndDeductionsPostingProfileId = _metVendorRebateTableContract.parmRebatePostingId();
        rebateTable.RebateAgreementType = _metVendorRebateTableContract.parmRebateAgreementType();
        rebateTable.DocumentNotes = _metVendorRebateTableContract.parmDocumentNotes();
        rebateTable.METVendRebateTypeId = _metVendorRebateTableContract.parmVendorRebateType();

        // Bug 308204: CB201 - There is no 'Charge Through' or 'Warehouse Sales' filter for sales based Customer rebate calculation
        rebateTable.METItemDistributionMethod = _metVendorRebateTableContract.parmItemDistributionMethod();

        rebateTable.defaultRow(); // Added to ensure all mandatory fields are populated;
        //Populate attributes 
        if (rebateTable.PriceComponentCombinationName)
        {               
            combination = GUPPriceComponentCodePriceAttributeGroupCombination::findByNameAndComponentTypeAndCodeName(rebateTable.PriceComponentCombinationName, GUPPriceComponent::RebateManagement, rebateTable.PriceComponentCodeName);
            rebateTable.PriceComponentCombination = combination.RecId;
            rebateTable.PricingRuleLine = GUPPricingRule::findOrCreatePricingRuleFromEntity(rebateTable, GUPPricingAttributeSourceLevel::Line, rebateTable.LineExclusionType, combination.LinePriceAttributeGroupName, rebateTable.LineExclusion);              
        }
        if (rebateTable.validateWrite())
        {
            rebateTable.insert();
        }
        else
        {
            throw Exception::Error;
        }
        result = METProcessingStatus::Success;
        message = strFmt("@MET:RebateDealHeaderCreated", rebateTable.AgreementNumber);


        tamRebateDateList = _metVendorRebateTableContract.parmMETTAMRebateDateContractArray();
        if(tamRebateDateList)
        {
            literator = new ListIterator(tamRebateDateList);
            while (literator.more())
            {
                metTAMRebateDateContract = literator.value();
                resultCon = this.createRebateDate(metTAMRebateDateContract, rebateTable.AgreementNumber);
                result = conPeek(resultCon, 1);
                message += conPeek(resultCon, 2);
                literator.next();
            }
        }

        tamRebateLineList = _metVendorRebateTableContract.parmMETTAMRebateLineContract();
        if(tamRebateLineList)
        {
            literator = new ListIterator(tamRebateLineList);
            while (literator.more())
            {
                metTAMRebateLineContract = literator.value();
                resultCon = this.createRebateLine(metTAMRebateLineContract, rebateTable.AgreementNumber);
                result = conPeek(resultCon, 1);
                message += conPeek(resultCon, 2);
                literator.next();
            }
        }
    }
    catch (Exception::Deadlock)
    {
        retry;
    }
    catch (Exception::UpdateConflict)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() >= #RetryNum)
            {
                result = METProcessingStatus::Error;
                message = this.getErrorStr();
            }
            else
            {
                retry;
            }
        }
        else
        {
            result = METProcessingStatus::Error;
            message = this.getErrorStr();
        }
    }
    catch
    {
        result = METProcessingStatus::Error;
        message = this.getErrorStr();
    }

    return [result, message];

}

